main() {
    variable heading = 0
    loop {
        heading = heading - 90
        if (heading < 0) {
            heading = heading + 360
        }
        if ({{sensor}}.distance(heading) < 1) {
            heading = heading + 90
            if ({{sensor}}.distance(heading) < 1) {
                heading = heading + 90
                if ({{sensor}}.distance(heading) < 1) {
                    heading = heading + 90
                }
            }
        }
        if (heading >= 360) {
            heading = heading - 360
        }
        {{drive}}.move(heading, 1)
    }
}
